292	  protected readonly error = signal<string | null>(null);
293	  /** The refusal of the last action taken on a person's row, shown on that row. */
294	  protected readonly personError = signal<{ id: number; message: string } | null>(null);
295	  /** The person chosen in each row's patron list, by person id. */
296	  protected readonly patronChoices = new Map<number, string>();
297	  /** The refusal of the last patron added on a person's row, shown on that row. */
298	  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
299	  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
300	  private busy = false;
301	
302	  constructor() {
303	    // Every sheet load re-reads the sheet's people from the store.
304	    effect(() => {
305	      const sheet = this.session.sheet();
306	      this.session.loads();
307	      untracked(() => {
308	        this.people.set([]);
309	        this.claims.set([]);
310	        this.rates.set([]);
311	        this.periods.set([]);
312	        this.reset();
313	        this.personError.set(null);
314	        this.retireDates.clear();
315	        this.patronError.set(null);
316	        this.patronChoices.clear();
317	        if (sheet) void this.reload(sheet);
318	      });
319	    });
320	  }
321	
322	  protected claimsOf(personId: number): ClaimView[] {
323	    return this.byPerson().get(personId) ?? [];
324	  }
325	
326	  /** A person's claims that count in the live totals (see countsLive). */
327	  private countingOf(personId: number): ClaimView[] {
328	    const person = this.people().find((p) => p.id === personId);
329	    return person ? this.claimsOf(personId).filter((c) => countsLive(c, person)) : [];
330	  }
331	
332	  /** What a person has claimed: the sum of their OPEN and SETTLED claims' amounts (see countsLive). */
333	  protected claimed(personId: number): string {
334	    return money(this.claimedCents(personId));
335	  }
336	
337	  private claimedCents(personId: number): number {
338	    return this.countingOf(personId).reduce((sum, c) => sum + cents(c.amount), 0);
339	  }
340	
341	  /** A person's overdue claims that count in the live totals (see countsLive). */
342	  protected overdueOf(personId: number): ClaimView[] {
343	    return this.countingOf(personId).filter((c) => overdue(c, this.session.terms(), this.today()));
344	  }
345	
346	  /** The due of a person's counting overdue claims added up (a claim with no figure adds nothing). */
347	  protected overdueTotalOf(person: PersonView): string {
348	    return money(this.overdueCents(person));
349	  }
350	
351	  private overdueCents(person: PersonView): number {
352	    return this.overdueOf(person.id).reduce(
353	      (sum, c) => sum + (this.dueCents(c, person) ?? 0),
354	      0,
355	    );
356	  }
357	
358	  /** The grade a person has in force on the sheet's today. */
359	  protected gradeOf(person: PersonView): Grade {
360	    return gradeOn(person.grades, this.today());
361	  }
362	
363	  /** The rate a grade has in force on the sheet's today (a two-decimal percent), or null when it has none. */
364	  protected pctOf(grade: Grade): string | null {
365	    return rateOn(this.rates(), grade, this.today());
366	  }
367	
368	  /** A person's due-total: the sum of their counting claims' due figures, or n/a (see dueTotalCents). */
369	  protected dueTotalOf(person: PersonView): string {
370	    const total = this.dueTotalCents(person);
371	    return total === null ? NO_RATE : money(total);
372	  }
373	
374	  /**
375	   * A person's due-total in whole cents: the sum of the due figures of their OPEN and SETTLED claims
376	   * (0 with none; see countsLive). Null (n/a) when the grade they have in force on the sheet's today has no
377	   * rate, unless a claim has a figure (a fixed one, or one at the grade in force on its own date): then it
378	   * is the sum of the figures there are.
379	   */
380	  private dueTotalCents(person: PersonView): number | null {
381	    const dues = this.countingOf(person.id).map((c) => this.dueCents(c, person));
382	    if (this.pctOf(this.gradeOf(person)) === null && dues.every((d) => d === null)) return null;
383	    return dues.reduce<number>((sum, d) => sum + (d ?? 0), 0);
384	  }
385	
386	  /**
387	   * A claim's due in whole cents at the grade its person has in force on its date, with its late charge
388	   * (see claimDueCents).
389	   */
390	  private dueCents(claim: ClaimView, person: PersonView): number | null {
391	    return claimDueCents(claim, this.rates(), gradeOn(person.grades, claim.date), this.floorCents(), this.late());
392	  }
393	
394	  /** A person's patrons' names, sorted, comma and space separated. */
395	  protected patronsOf(person: PersonView): string {
396	    return this.patrons(person)
397	      .map((p) => p.name)
398	      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
399	      .join(', ');
400	  }
401	
402	  /** A person's backing: their patrons' due-totals added up, skipping those shown as n/a. */
403	  protected backingOf(person: PersonView): string {
404	    return money(this.patrons(person).reduce((sum, p) => sum + (this.dueTotalCents(p) ?? 0), 0));
405	  }
406	
407	  private patrons(person: PersonView): PersonView[] {
408	    return this.people().filter((p) => person.patronIds.includes(p.id));
409	  }
410	
411	  /** Name the person chosen on a person's row as their patron. */
412	  protected async addPatron(person: PersonView): Promise<void> {
413	    this.patronError.set(null);
414	    this.personError.set(null);
415	    const sheet = this.session.sheet();
416	    if (!sheet) return;
417	    const patronId = Number(this.patronChoices.get(person.id) ?? '');
418	    const refuse = (message: string) => this.patronError.set({ id: person.id, message });
419	    if (!patronId) {
420	      refuse('Choose a person to add as a patron.');
421	      return;
422	    }
423	    if (patronId === person.id) {
424	      refuse('A person cannot be their own patron.');
425	      return;
426	    }
427	    if (person.patronIds.includes(patronId)) {
428	      refuse('That person is already a patron.');
429	      return;
430	    }
431	    try {
432	      const saved = await this.api.addPatron(sheet, person.id, patronId);
433	      if (this.session.sheet() !== sheet) return;
434	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
435	    } catch {
436	      refuse('The patron could not be added.');
437	    }
438	  }
439	
440	  /** The last statement's due-total: n/a when it was, empty when none was taken. */
441	  protected statedTotalOf(person: PersonView): string {
442	    if (person.statementCount === 0) return '';
443	    return person.statementTotal ?? NO_RATE;
444	  }
445	
446	  /** Take a statement for a person: the row and their claims show what the store holds after it. */
447	  protected async statement(person: PersonView): Promise<void> {
448	    this.personError.set(null);
449	    const sheet = this.session.sheet();
450	    if (!sheet) return;
451	    try {
452	      const stated = await this.api.statement(sheet, person.id);
453	      if (this.session.sheet() !== sheet) return;
454	      this.people.update((list) => list.map((p) => (p.id === stated.person.id ? stated.person : p)));
455	      const byId = new Map(stated.claims.map((c) => [c.id, c]));
456	      this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
457	    } catch {
458	      this.personError.set({ id: person.id, message: 'The statement could not be taken.' });
459	    }
460	  }
461	
462	  /** Retire a person from the date typed on their row, or from the sheet's today with none. */
463	  protected async retire(person: PersonView): Promise<void> {
464	    this.personError.set(null);
465	    const sheet = this.session.sheet();
466	    if (!sheet) return;
467	    const from = this.retireDates.get(person.id)?.trim() || null;
468	    try {
469	      const retired = await this.api.retire(sheet, person.id, from);
470	      if (this.session.sheet() !== sheet) return;
471	      this.people.update((list) => list.map((p) => (p.id === retired.id ? retired : p)));
472	    } catch {
473	      this.personError.set({ id: person.id, message: 'The person could not be retired.' });
474	    }
475	  }
476	
477	  /** Put a person on hold, or take them off it. */
478	  protected async toggleHold(person: PersonView): Promise<void> {
479	    this.personError.set(null);
480	    const sheet = this.session.sheet();
481	    if (!sheet) return;
482	    try {
483	      const saved = await this.api.hold(sheet, person.id, !person.held);
484	      if (this.session.sheet() !== sheet) return;
485	      this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
486	    } catch {
487	      this.personError.set({
488	        id: person.id,
489	        message: person.held ? 'The person could not be released.' : 'The person could not be put on hold.',
490	      });
491	    }
492	  }
493	
494	  /** A rate set for a grade, in place of any it had from the same date. */
495	  protected rateSaved(rate: RateView): void {
496	    this.rates.update((list) => [...list.filter((r) => !sameSlot(r, rate)), rate]);
497	  }
498	
499	  /** A period added, kept in from-date order. */
500	  protected periodSaved(period: PeriodView): void {
501	    this.periods.update((list) => [...list, period].sort((a, b) => a.from.localeCompare(b.from)));
502	  }
503	
504	  /** A period closed or reopened, in its place. */
505	  protected periodChanged(period: PeriodView): void {
506	    this.periods.update((list) => list.map((p) => (p.id === period.id ? period : p)));
507	  }
508	
509	  /** A claim added (listed first, as the newest) or saved or moved (in its place). */
510	  protected claimSaved(claim: ClaimView): void {
511	    this.claims.update((list) =>
512	      list.some((c) => c.id === claim.id) ? list.map((c) => (c.id === claim.id ? claim : c)) : [claim, ...list],
513	    );
514	  }
515	
516	  /** A claim quick-added: its person listed when they were added for it, the claim first as the newest. */
517	  protected quickAdded(added: QuickAddView): void {
518	    if (added.personAdded) this.people.update((list) => [...list, added.person]);
519	    this.claimSaved(added.claim);
520	  }
521	
522	  protected value(event: Event): string {
523	    return (event.target as HTMLInputElement).value;
524	  }
525	
526	  protected checked(event: Event): boolean {
527	    return (event.target as HTMLInputElement).checked;
528	  }
529	
530	  protected gradeChosen(event: Event): Grade {
531	    return (event.target as HTMLSelectElement).value as Grade;
532	  }
533	
534	  /** Open a person's editor: the form takes their values. */
535	  protected open(person: PersonView): void {
536	    this.personError.set(null);
537	    this.editing.set(person.id);
538	    this.version.set(person.version);
539	    this.name.set(person.name);
540	    this.grade.set(this.gradeOf(person));
541	    this.gradeFrom.set(this.today());
542	    this.error.set(null);
543	  }
544	
545	  protected reset(): void {
546	    this.editing.set(null);
547	    this.name.set('');
548	    this.grade.set('A');
549	    this.gradeFrom.set(this.today());
550	    this.error.set(null);
551	  }
552	
553	  protected async save(event: Event): Promise<void> {
554	    event.preventDefault();
555	    if (this.busy) return;
556	    this.error.set(null);
557	    const sheet = this.session.sheet();
558	    if (!sheet) return;
559	    const form = { name: this.name(), grade: this.grade() };
560	    if (!form.name.trim()) {
561	      this.error.set('Type a name for the person.');
562	      return;
563	    }
564	    const id = this.editing();
565	    this.busy = true;
566	    try {
567	      if (id === null) {
568	        const added = await this.api.add(sheet, form);
569	        this.people.update((list) => [...list, added]);
570	      } else {
571	        const gradeFrom = this.gradeFrom().trim() || null;
572	        const saved = await this.api.edit(sheet, id, { ...form, gradeFrom, version: this.version() });
573	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
574	      }
575	      this.reset();
576	    } catch (e) {
577	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
578	        await this.showCurrent(sheet, id);
579	        this.error.set('Someone else has saved this person since you opened it. The form shows their values now.');
580	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
581	        this.error.set('That name is already in use on this sheet.');
582	      } else {
583	        this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
584	      }
585	    } finally {
586	      this.busy = false;
587	    }
588	  }
589	
590	  /** Someone else saved the person open in the form: show what the store holds for them now. */
591	  private async showCurrent(sheet: string, id: number): Promise<void> {
592	    try {
593	      const current = (await this.api.list(sheet)).find((p) => p.id === id);
594	      if (!current || this.session.sheet() !== sheet || this.editing() !== id) return;
595	      this.people.update((list) => list.map((p) => (p.id === id ? current : p)));
596	      this.version.set(current.version);
597	      this.name.set(current.name);
598	      this.grade.set(this.gradeOf(current));
599	    } catch {
600	      // the form keeps what was typed; the refusal is still shown
601	    }
602	  }
603	
604	  private async reload(sheet: string): Promise<void> {
605	    const loads = this.session.loads();
606	    const [people, claims, rates, periods] = await Promise.all([
607	      this.api.list(sheet),
608	      this.claimsApi.list(sheet),
609	      this.ratesApi.list(sheet),
610	      this.periodsApi.list(sheet),
611	    ]);
612	    // A later load may have started while this one was in flight: only the latest is shown.
613	    if (this.session.sheet() === sheet && this.session.loads() === loads) {
614	      this.claims.set(claims);
615	      this.rates.set(rates);
616	      this.periods.set(periods);
617	      this.people.set(people);
618	    }
619	  }
620	}
